import React, { useEffect, useRef, useState, useCallback } from "react";
import ReactDOM from "react-dom";
import { Icon } from "semantic-ui-react";

const EnterFullscreenIcon = () => (
  <Icon name="zoom-in" size="large" />
);

const ExitFullscreenIcon = () => (
  <Icon name="zoom-out" size="large" />
);

type FullscreenOverlayProps = {
  children: React.ReactNode;
  isOpen: boolean;
  onClose: () => void;
};

const FullscreenOverlay: React.FC<FullscreenOverlayProps> = ({ children, isOpen, onClose }) => {
  const overlayContainer = useRef(null);

  if (!overlayContainer.current) {
    overlayContainer.current = document.createElement("div");
  }

  useEffect(() => {

    // Apply styles
    overlayContainer.current.style.cssText = `
      position: fixed;
      place-items: center;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      display: none; /* Initially hidden */
      z-index: 1000;
      background-color: rgba(0, 0, 0, 0.75);
      overflow: auto;
    `;

    document.body.appendChild(overlayContainer.current);

    // Attach event listener for closing the overlay
    const handleOverlayClick = (event: MouseEvent) => {
      if (event.target === overlayContainer.current) {
        onClose();
      }
    };
    overlayContainer.current.addEventListener("click", handleOverlayClick);

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      overlayContainer.current.removeEventListener("click", handleOverlayClick);
      document.body.removeChild(overlayContainer.current);
    };
  }, [onClose]);

  useEffect(() => {
    if (isOpen) {
      overlayContainer.current.style.display = "flex";
    } else {
      overlayContainer.current.style.display = "none";
    }
  }, [isOpen]);

  const contentStyle = {
    background: "white",
    flexGrow: "1",
    margin: "auto",
  };

  const content = <div style={contentStyle}>{children}</div>;

  return isOpen ? ReactDOM.createPortal(
    content,
    overlayContainer.current,
  ) : null;
};

type FSClickProps = {
  children: ReactElement;
};

const FSClick: React.FC<FSClickProps> = ({ children }) => {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showIcon, setShowIcon] = useState(false);

  const handleIconClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    setIsFullscreen(true);
    event.preventDefault();
  };

  // useCallback says that handleClose does not depend on state!
  const handleClose = useCallback(() => {
    setIsFullscreen(false);
  }, []);

  // Stops propagation of click events to children
  const handleChildClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    setIsFullscreen(false);
  };

  const handleMouseEnter = () => {
    setShowIcon(true);
  };

  const handleMouseLeave = () => {
    setShowIcon(false);
  };

  // Define the style for the SVG to be positioned in the top right corner
  const svgStyle = {
    backgroundColor: "white",
    borderBottom: "1px solid gray",
    borderBottomLeftRadius: "10px",
    borderLeft: "1px solid gray",
    cursor: "pointer",
    display: "block", // Make sure the SVG is always shown
    opacity: "0.8",
    padding: "5px",
    position: "absolute",
    right: "0px", // Adjust the position as needed
    top: "0px", // Adjust the position as needed
    zIndex: 1,
  };

  return (
    <>
      <div style={{ cursor: "pointer", position: "relative" }}
        onClick={handleIconClick}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}>
        {showIcon && <div style={svgStyle} onClick={handleIconClick}><EnterFullscreenIcon /></div>}
        {children}
      </div>

      {isFullscreen && (
        <FullscreenOverlay isOpen={isFullscreen} onClose={handleClose}>
          <div style={svgStyle} onClick={handleChildClick}>
            <ExitFullscreenIcon style={svgStyle} onClick={handleClose} />
          </div>
          <div>
            {children}
          </div>
        </FullscreenOverlay>
      )}
    </>
  );
};

export {FullscreenOverlay};

export default FSClick;
